import{z as o,x as s,o as e,c as B,q as i,j as A,D as t,d as r,s as p,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"前向稳定与后向稳定","description":"","frontmatter":{"title":"前向稳定与后向稳定","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/forward-backward-stability.md","filePath":"cs/forward-backward-stability.md","lastUpdated":1791063341000}'),d={name:"cs/forward-backward-stability.md"};function u(m,a,h,D,f,c){const l=s("Mermaid");return e(),B("div",null,[a[2]||(a[2]=i('<h1 id="前向稳定与后向稳定" tabindex="-1">前向稳定与后向稳定 <a class="header-anchor" href="#前向稳定与后向稳定" aria-label="Permalink to &quot;前向稳定与后向稳定&quot;">​</a></h1><div class="epigraph"><p>后向稳定说：机器算出的是一个近旁问题的精确解；前向稳定说：机器解与真解的差被条件数允许的量级兜住。</p><footer>—— 据 Higham, Accuracy and Stability of Numerical Algorithms；Trefethen and Bau, Numerical Linear Algebra 整理</footer></div><p>上一课<a href="/cs/condition-number">条件数</a>把问题敏感度从算法里抽出。本课不重导 \\(\\kappa\\)，也不从 IEEE 舍入模式另起。缺口是：\\(\\gamma_n\\) 跟踪的是运算注入，条件数跟踪的是 \\(f\\)——<strong>怎样把「算法够不够好」说成一句可检验的话</strong>。Higham 的前向/后向误差就是这句。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真解 \\(y=f(x)\\)，机器给出 \\(\\hat y\\)。前向误差是 \\(\\hat y\\) 与 \\(y\\) 的差（相对或绝对）。后向误差是：存在多重小扰动 \\(\\delta x\\)，使得 \\(\\hat y=f(x+\\delta x)\\)；其中最小的 \\(\\|\\delta x\\|\\) 量级就是后向误差。缺口因此不是再举一个溢出例子，而是<strong>改写问题</strong>：不把 \\(\\hat y\\) 当成「算错的 \\(y\\)」，而问它是不是「稍稍改过的数据上的正确 \\(y\\)」。后向小，则前向大约被 \\(\\kappa\\) 放大，与上一课衔接。</p><p>许多分解算法（后课高斯消元）逐条指令的前向误差难看清，后向图像却干净：算出的因子是某个 \\(A+\\Delta A\\) 的精确因子。这是数值线性代数的标准叙事。本课先定义，消元细节下一单元再给。</p><h3 id="后向稳定不是「结果很准」" tabindex="-1">后向稳定不是「结果很准」 <a class="header-anchor" href="#后向稳定不是「结果很准」" aria-label="Permalink to &quot;后向稳定不是「结果很准」&quot;">​</a></h3><p>后向稳定而病态：\\(\\hat y\\) 对真 \\(y\\) 仍可差很远，只是对某个近旁问题很准。用户若把数据当绝对真，会误以为算法失败。前向稳定更强、更少见：它要求 \\(\\hat y\\) 接近 \\(y\\)，哪怕你不改写数据。不稳定指后向误差远大于舍入单位，例如灾难抵消后的公式。三种词不能互换。</p><p><span class="marginnote">直觉类比：后向稳定像考试时把题目里的 25 看成了 52，却把这道「52 版」的题做得步步精确、答案全对——解题过程无可指摘，只是解的不是原来那道题。前向稳定则要求「原题答案就得接近标准答案」，标准高得多。</span></p><p><span class="marginnote">Trefethen and Bau Lecture 12–14 把后向稳定当作算法的合格线。Higham 强调：后向误差用数据的范数量，前向误差用解的范数量，中间隔着条件数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检验后向稳定：把残量或等价扰动写出来，看 \\(\\|\\Delta A\\|/\\|A\\|\\) 是否 \\(O(u)\\)。前向：直接比 \\(\\hat y\\) 与（更高精度或解析的）\\(y\\)。混合：先证后向，再乘 \\(\\kappa\\) 得前向估计。残量小不等于解准——那正是 \\(\\kappa\\) 大时的现象；残量小通常支持后向小。</p><p><span class="marginnote">数字实例：双精度的舍入单位 \\(u\\approx 2\\times 10^{-16}\\)。若条件数 \\(\\kappa=10^4\\)，后向稳定的算法前向误差约 \\(\\kappa u\\approx 10^{-12}\\)，也就是约 12 位有效数字可信；若 \\(\\kappa=10^{16}\\)，\\(\\kappa u\\approx 1\\)——连第一位有效数字都保不住。同一算法，只是问题换了，可信位数就差了 12 位。</span></p>',13)),(e(),A(n,null,{default:t(()=>[p(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%95%B0%E6%8D%AE%20x%22%5D%20--%3E%20F%5B%22%E7%B2%BE%E7%A1%AE%20f%22%5D%0A%20%20F%20--%3E%20Y%5B%22%E7%9C%9F%E8%A7%A3%20y%22%5D%0A%20%20X%20--%3E%20ALG%5B%22%E6%9C%BA%E5%99%A8%E7%AE%97%E6%B3%95%22%5D%0A%20%20ALG%20--%3E%20YH%5B%22%E6%9C%BA%E5%99%A8%E8%A7%A3%22%5D%0A%20%20YH%20--%3E%20BWD%5B%22%E5%90%8E%E5%90%91%EF%BC%9A%E8%BF%91%E6%97%81%E6%95%B0%E6%8D%AE%E4%B8%8A%E7%9A%84%E7%B2%BE%E7%A1%AE%E8%A7%A3%22%5D%0A%20%20YH%20--%3E%20FWD%5B%22%E5%89%8D%E5%90%91%EF%BC%9A%E4%B8%8E%20y%20%E7%9A%84%E5%B7%AE%22%5D%0A%20%20KAPPA%5B%22%E6%9D%A1%E4%BB%B6%E6%95%B0%22%5D%20--%3E%20FWD%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"「逐步」后向稳定：每一步都是对当时输入的后向精确。复合之后整体后向是否仍小，要另证；这是后课消元与迭代各自要做的。",-1)),a[4]||(a[4]=E("p",null,"前向误差界 \\(\\kappa\\times\\) 后向误差是一阶图像，忽略 \\(\\kappa\\,u\\approx 1\\) 时的非线性。当问题已经病到机器精度下不可分辨多个解，稳定算法会交出「某一个近旁问题的解」，不同实现可以差得很远却都后向合格。规格若要求位对位相同，必须固定算法、顺序与舍入模式，而不是只要求稳定。消去课会给出公式级的反例：代数恒等变换可以毁掉后向稳定。先把合格线定在后向上，再去改写公式。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"后向观点匹配浮点的 \\((1+\\delta)\\)：每步都在改数据。若整条算法等价于「只在入口改一次 \\(O(u)\\) 再精确算下去」，用户可以诚实地说：我解的是测量误差范围内的问题。前向观点匹配「我必须拿到这个 \\(y\\)」。求值病态的 \\(f\\) 时，后向稳定是合理目标；前向稳定可能要求改问题（换基、换未知量）。下一课消去会展示：代数等价的公式可以一个后向稳定、一个不是。",-1)),a[7]||(a[7]=E("p",null,"混合稳定允许后向误差用稍大的范数或分量意义来量，前向仍被 \\(\\kappa\\) 控制。实践中 BLAS 的常数因子可以是 \\(n\\) 的低次多项式，仍视为稳定。对照：显式形成法向量 \\(A^\\top A\\) 再消元，是经典的不稳定——\\(\\kappa\\) 被平方。算法选择在此比调 \\(u\\) 更重要。残量小、后向小、前向大，是在告诉你问题病态，数据不支撑你要的那些位数。把三种误差画在同一张图上，数值课剩下的消元、迭代、牛顿、插值才有共同语言。",-1)),a[8]||(a[8]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者看到「换个 BLAS 库结果就不同」就断定有 bug。在病态问题上，两个都后向合格的实现交出的本来就是「不同近旁问题的解」——各自精确、彼此可以差很远。这时候该查的是问题的条件数，而不是给库报缺陷。")],-1)),(e(),A(n,null,{default:t(()=>[p(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20ALG%5B%22%E5%90%8E%E5%90%91%E7%A8%B3%E5%AE%9A%E7%AE%97%E6%B3%95%22%5D%20--%3E%20BE%5B%22%E5%90%8E%E5%90%91%E8%AF%AF%E5%B7%AE%E7%BA%A6%20u%E2%89%882e-16%22%5D%0A%20%20BE%20--%3E%20Q%7B%22%E9%97%AE%E9%A2%98%E6%9D%A1%E4%BB%B6%E6%95%B0%20%CE%BA%20%E5%A4%9A%E5%A4%A7%3F%22%7D%0A%20%20Q%20--%20%22%CE%BA%E2%89%881e4%22%20--%3E%20OK%5B%22%E5%89%8D%E5%90%91%E8%AF%AF%E5%B7%AE%E2%89%88%CE%BA%C2%B7u%E2%89%881e-14%2C12%20%E4%BD%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20Q%20--%20%22%CE%BA%E2%89%881e16%22%20--%3E%20BAD%5B%22%CE%BA%C2%B7u%E2%89%881%2C%E8%BF%9E%E4%B8%80%E4%BD%8D%E9%83%BD%E4%B8%8D%E4%BF%9D%22%5D%0A%20%20BAD%20--%3E%20VER%5B%22%E4%B8%8D%E6%98%AF%E7%AE%97%E6%B3%95%E5%A4%B1%E8%81%8C%2C%E6%98%AF%E6%95%B0%E6%8D%AE%E7%97%85%E6%80%81%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明某条 BLAS 的常数，不把混合稳定的细分类写完。下一课<a href="/cs/catastrophic-cancellation">消去与灾难抵消</a>给最常见的不稳定模式。后课默认：好算法首先追求后向稳定；前向误差用 \\(\\kappa\\) 估计；残量小不保证解准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后向误差：\\(\\hat y\\) 是近旁数据的精确解；前向误差：\\(\\hat y\\) 与真 \\(y\\) 的差。</li><li>后向稳定 \\(\\times\\) 条件数 \\(\\approx\\) 前向误差量级。</li><li>病态且后向稳定时，解可以仍不准，算法却已尽责。</li><li>下一课看代数等价公式如何失去后向稳定。</li><li>出处：Higham；Trefethen and Bau。</li></ul>',4))])}const y=o(d,[["render",u]]);export{b as __pageData,y as default};
